const client = new RedwoodClient({ apiKey: process.env.REDWOOD_API_KEY!, experimental: { costModel: true } });

const estimate = await client.experimental.costModel.estimate({
  scmVersion: "v1",
  mode: "estimate",
  workload: {
    model: "llama-3.1-70b-instruct",
    region: "us-east-1",
    gpuSku: "h100-sxm",
    tokens: { input: 1200, output: 300 },
    batch: { batchSizeEffective: 6 },
    cache: { kvCacheHitRate: 0.35 }
  }
});

console.log(estimate.total.costUsd, estimate.breakdown.compute.costUsd);

// If experimental.costModel is accessed without enabling the flag, we throw:
// "Cost Model API client is experimental. Enable via { experimental: { costModel: true } }."
